# Generated by scripts/theme.py; source after application defaults.
export BAT_THEME=Dotfiles
export DOTFILES_FZF_COLOR='dark,fg:#D8DEE9,bg:#2E3440,fg+:#ECEFF4,bg+:#434C5E,hl:#A3BE8C,hl+:#A3BE8C,pointer:#88C0D0,marker:#A3BE8C,header:#88C0D0,prompt:#88C0D0,info:#81A1C1,border:#4C566A,spinner:#88C0D0'
case " ${FZF_DEFAULT_OPTS-} " in
    *" --color=$DOTFILES_FZF_COLOR "*) ;;
    *) export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=$DOTFILES_FZF_COLOR" ;;
esac
